python
def receiptArithmeticFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    for x in a: out.append(2*x+3)
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int receiptArithmeticFirstQualifyingSlip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a)out.add(2*x+3);}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
